import sys

class Product:
    def __init__(self, name, price, seller):
        self.name = name
        self.price = price
        self.seller = seller

    def print_details(self):
        pass

class NewProduct(Product):
    def print_details(self):
        print(f"New Product: {self.name}, Price: ${self.price}, Seller: {self.seller}")

class UsedProduct(Product):
    def __init__(self, name, price, seller, condition):
        super().__init__(name, price, seller)
        self.condition = condition

    def print_details(self):
        print(f"Used Product: {self.name}, Price: ${self.price}, Seller: {self.seller}, Condition: {self.condition}")

def main():
    lines = sys.stdin.read().strip().split('\n')
    products = []

    for line in lines:
        if not line.strip():
            continue
        parts = [p.strip() for p in line.split(',')]
        if len(parts) == 3:
            name, price, seller = parts
            products.append(NewProduct(name, float(price), seller))
        elif len(parts) == 4:
            name, price, seller, condition = parts
            products.append(UsedProduct(name, float(price), seller, condition))

    for product in products:
        product.print_details()

if __name__ == "__main__":
    main()
